/*
 * Low-level GC570D bridge helpers, interrupt handling, Xilinx register access,
 * and shared hardware diagnostics.
 */
#include "gc570d.h"
/* Default 3000-nit HDR-to-SDR curve generated by the official driver. */
#include "../data/gc570d_hdr_lut_3000.inc"


#define GC570D_I2C_IRQS (GC570D_IRQ_I2C0 | GC570D_IRQ_I2C1 | \
			 GC570D_IRQ_I2C2 | GC570D_IRQ_I2C3)
/* Let a control transaction survive a starved DMA1 descriptor and its reset. */
#define GC570D_CONTROL_IRQ_TIMEOUT_US 3000000

bool gc570d_subsystem_busy(struct gc570d_dev *gc)
{
	return READ_ONCE(gc->video_streaming) ||
	       READ_ONCE(gc->video0_streaming) ||
	       READ_ONCE(gc->audio_prepared) ||
	       READ_ONCE(gc->audio0_prepared);
}

void gc570d_control_irq_prepare(struct gc570d_dev *gc, u32 irq)
{
	/* Drain an ISR which may already have sampled the previous completion. */
	writel(irq, gc->bar0 + GC570D_REG_IRQ_STATUS);
	synchronize_irq(gc->irq);
	atomic_andnot(irq, &gc->control_irq_seen);
	writel(irq, gc->bar0 + GC570D_REG_IRQ_STATUS);
}

int gc570d_control_irq_wait(struct gc570d_dev *gc, u32 irq,
				    u32 *observed_irq)
{
	u32 status;
	int ret;

	ret = readl_poll_timeout(gc->bar0 + GC570D_REG_IRQ_STATUS, status,
				 (status & irq) ||
				 (atomic_read(&gc->control_irq_seen) & irq),
				 10, GC570D_CONTROL_IRQ_TIMEOUT_US);
	*observed_irq = readl(gc->bar0 + GC570D_REG_IRQ_STATUS) |
		(u32)atomic_read(&gc->control_irq_seen);
	return ret;
}

void gc570d_control_irq_finish(struct gc570d_dev *gc, u32 irq)
{
	writel(irq, gc->bar0 + GC570D_REG_IRQ_STATUS);
	atomic_andnot(irq, &gc->control_irq_seen);
}



/* capture_lock serializes shared INTx ownership for every video/audio DMA. */
void gc570d_video_irq_get_locked(struct gc570d_dev *gc)
{
	if (gc->video_irq_users++ == 0)
		enable_irq(gc->irq);
}

void gc570d_video_irq_put_locked(struct gc570d_dev *gc)
{
	if (WARN_ON(!gc->video_irq_users))
		return;
	if (--gc->video_irq_users == 0)
		disable_irq(gc->irq);
}

